const totalItems = allItems.reduce((sum, s) => sum + s.items.length, 0);
console.log(`Total items: ${totalItems}`);

function generateDetailedPDF() {
  const doc = new PDFDocument({ size: 'A4', margins: { top: 40, bottom: 40, left: 35, right: 35 }, bufferPages: true });
  const out = fs.createWriteStream('PMG-OS-Checklist-Detailed.pdf');
  doc.pipe(out);

  doc.rect(0, 0, doc.page.width, 100).fill('#0F172A');
  doc.fontSize(24).fill('#FFFFFF').font('Helvetica-Bold').text('PMG GROUP OS', 35, 18, { align: 'center' });
  doc.fontSize(11).fill('#F87171').text('Complete Testing & Verification Checklist — DETAILED', { align: 'center' });
  doc.fontSize(8).fill('#94A3B8').text(`${totalItems} Test Items · Full Mode Descriptions · HOW IT WORKS for Every Item`, { align: 'center' });
  doc.y = 110;

  doc.fontSize(8).fill('#374151').font('Helvetica-Bold').text('Login: ', { continued: true }).font('Helvetica').text('shershah_nawabi@pmggroup-llc.com / PMGAdmin2024!');
  doc.moveDown(0.2);
  doc.font('Helvetica-Bold').text('Status: ', { continued: true }).font('Helvetica').text('PASS | PARTIAL | FAIL | N/A');
  doc.moveDown(0.2);
  doc.font('Helvetica').text('Each item has: HOW IT WORKS + behavior in each AI mode + EXPECTED RESULT + space for YOUR STATUS and NOTES.');
  doc.moveDown(0.5);

  for (const section of allItems) {
    if (doc.y > doc.page.height - 100) doc.addPage();
    const sy = doc.y;
    doc.rect(35, sy, doc.page.width - 70, 20).fill('#DC2626');
    doc.fontSize(10).fill('#FFFFFF').font('Helvetica-Bold').text(section.section, 42, sy + 5);
    doc.y = sy + 25;

    for (const item of section.items) {
      const blockH = 200;
      if (doc.y + blockH > doc.page.height - 40) doc.addPage();

      const lx = 35;
      const rw = doc.page.width - 70;

      doc.fontSize(9).fill('#DC2626').font('Helvetica-Bold').text(`${item.num}`, lx, doc.y, { continued: true });
      doc.fill('#0F172A').text(` — ${item.title}`);
      doc.moveDown(0.2);

      const labels = ['HOW IT WORKS:', 'IN AI AUTONOMOUS MODE:', 'IN HYBRID MODE:', 'IN HUMAN CONTROLLED MODE:', 'EXPECTED RESULT:'];
      const vals = [item.how, item.ai, item.hybrid, item.human, item.expected];
      for (let i = 0; i < labels.length; i++) {
        if (doc.y > doc.page.height - 60) doc.addPage();
        doc.fontSize(7).fill('#DC2626').font('Helvetica-Bold').text(labels[i], lx + 5, doc.y, { width: rw - 10 });
        doc.fontSize(7).fill('#374151').font('Helvetica').text(vals[i], lx + 5, doc.y, { width: rw - 10 });
        doc.moveDown(0.15);
      }

      if (doc.y > doc.page.height - 50) doc.addPage();
      doc.fontSize(7).fill('#0F172A').font('Helvetica-Bold').text('YOUR STATUS (circle one):   ', lx + 5, doc.y, { continued: true });
      doc.fill('#16A34A').text('PASS', { continued: true });
      doc.fill('#0F172A').text('   /   ', { continued: true });
      doc.fill('#D97706').text('PARTIAL', { continued: true });
      doc.fill('#0F172A').text('   /   ', { continued: true });
      doc.fill('#DC2626').text('FAIL', { continued: true });
      doc.fill('#0F172A').text('   /   ', { continued: true });
      doc.fill('#6B7280').text('N/A');
      doc.moveDown(0.15);
      doc.fontSize(7).fill('#0F172A').font('Helvetica-Bold').text('YOUR NOTES:', lx + 5);
      doc.fontSize(7).fill('#CBD5E1').font('Helvetica').text('_______________________________________________________________________________', lx + 5);
      doc.moveDown(0.3);
      doc.strokeColor('#E2E8F0').lineWidth(0.3).moveTo(lx, doc.y).lineTo(lx + rw, doc.y).stroke();
      doc.moveDown(0.3);
    }
  }

  doc.end();
  return new Promise(r => out.on('finish', r));
}

async function generateDetailedWord() {
  const children = [];
  children.push(new Paragraph({ heading: HeadingLevel.TITLE, children: [new TextRun({ text: 'PMG GROUP OS', bold: true, size: 52, color: '0F172A', font: 'Arial' })] }));
  children.push(new Paragraph({ children: [new TextRun({ text: 'Complete Testing & Verification Checklist — DETAILED', size: 28, color: 'DC2626', font: 'Arial' })] }));
  children.push(new Paragraph({ children: [new TextRun({ text: `${totalItems} Test Items · Full Mode Descriptions · HOW IT WORKS for Every Item`, size: 18, color: '6B7280', font: 'Arial' })] }));
  children.push(new Paragraph({ text: '' }));
  children.push(new Paragraph({ children: [new TextRun({ text: 'Login: ', bold: true, size: 20, font: 'Arial' }), new TextRun({ text: 'shershah_nawabi@pmggroup-llc.com / PMGAdmin2024!', size: 20, font: 'Arial' })] }));
  children.push(new Paragraph({ children: [new TextRun({ text: 'Status: PASS | PARTIAL | FAIL | N/A', size: 20, font: 'Arial' })] }));
  children.push(new Paragraph({ children: [new TextRun({ text: 'Each item has: HOW IT WORKS + behavior in each AI mode + EXPECTED RESULT + YOUR STATUS + YOUR NOTES.', size: 20, font: 'Arial' })] }));
  children.push(new Paragraph({ text: '' }));

  for (const section of allItems) {
    children.push(new Paragraph({ spacing: { before: 400 }, shading: { type: ShadingType.SOLID, color: 'DC2626' }, children: [new TextRun({ text: `  ${section.section}`, bold: true, size: 26, color: 'FFFFFF', font: 'Arial' })] }));
    children.push(new Paragraph({ text: '' }));

    for (const item of section.items) {
      children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: `${item.num} — ${item.title}`, bold: true, size: 22, color: '0F172A', font: 'Arial' })] }));
      children.push(new Paragraph({ text: '' }));

      const pairs = [
        ['HOW IT WORKS:', item.how],
        ['IN AI AUTONOMOUS MODE:', item.ai],
        ['IN HYBRID MODE:', item.hybrid],
        ['IN HUMAN CONTROLLED MODE:', item.human],
        ['EXPECTED RESULT:', item.expected],
      ];
      for (const [label, val] of pairs) {
        children.push(new Paragraph({ children: [new TextRun({ text: label, bold: true, size: 16, color: 'DC2626', font: 'Arial' })]}));
        children.push(new Paragraph({ children: [new TextRun({ text: val, size: 16, color: '374151', font: 'Arial' })]}));
        children.push(new Paragraph({ text: '' }));
      }

      children.push(new Paragraph({ children: [
        new TextRun({ text: 'YOUR STATUS (circle one):     ', bold: true, size: 16, font: 'Arial' }),
        new TextRun({ text: 'PASS', bold: true, size: 16, color: '16A34A', font: 'Arial' }),
        new TextRun({ text: '   /   ', size: 16, font: 'Arial' }),
        new TextRun({ text: 'PARTIAL', bold: true, size: 16, color: 'D97706', font: 'Arial' }),
        new TextRun({ text: '   /   ', size: 16, font: 'Arial' }),
        new TextRun({ text: 'FAIL', bold: true, size: 16, color: 'DC2626', font: 'Arial' }),
        new TextRun({ text: '   /   ', size: 16, font: 'Arial' }),
        new TextRun({ text: 'N/A', bold: true, size: 16, color: '6B7280', font: 'Arial' }),
      ]}));
      children.push(new Paragraph({ text: '' }));
      children.push(new Paragraph({ children: [new TextRun({ text: 'YOUR NOTES:', bold: true, size: 16, font: 'Arial' })]}));
      children.push(new Paragraph({ children: [new TextRun({ text: '___________________________________________________________________________', size: 16, color: 'E5E7EB', font: 'Arial' })]}));
      children.push(new Paragraph({ children: [new TextRun({ text: '___________________________________________________________________________', size: 16, color: 'E5E7EB', font: 'Arial' })]}));
      children.push(new Paragraph({ text: '' }));
      children.push(new Paragraph({ children: [new TextRun({ text: '────────────────────────────────────────────────────────────────────', size: 14, color: 'CBD5E1', font: 'Arial' })]}));
    }
  }

  const docx = new Document({ sections: [{ children }] });
  const buf = await Packer.toBuffer(docx);
  fs.writeFileSync('PMG-OS-Checklist-Detailed.docx', buf);
}

async function main() {
  console.log('Generating Detailed PDF...');
  await generateDetailedPDF();
  console.log('Done: PMG-OS-Checklist-Detailed.pdf');

  console.log('Generating Detailed Word...');
  await generateDetailedWord();
  console.log('Done: PMG-OS-Checklist-Detailed.docx');
}

main().catch(console.error);
